factorB = vec2( 0.0 ,-512);
product = vec2( factorA.x*factorB.x - factorA.y*factorB.y, factorA.x*factorB.y + factorA.y*factorB.x);
numerator = vec2( 1.0 , 0.0 );
denominator = product;
fraction = vec2( numerator.x*denominator.x + numerator.y*denominator.y,   // the fractions real part
numerator.y*denominator.x - numerator.x*denominator.y)/  // the fractions imaginary part
(denominator.x*denominator.x + denominator.y*denominator.y);
uv = fraction.yx*vec2(-1, 1.0 ) * 20.0;
uv = mix(0.5 + (uvo-0.5) * 2.0,uv+0.5,0.5);
uv = 0.5 + (1.0 - abs( fract( uv * 0.5 ) * 2.0 - 1.0 )-0.5)*0.98; // Eo.S. mirror code with cutted borders
vec2 d = (vec2(1.0)/uTexSize);
vec3 dx = ( GetPixel(uv+vec2( 1.0 , 0.0 )*d)-GetPixel(uv-vec2( 1.0 , 0.0 )*d).xy );
vec3 dy = ( GetPixel(uv+vec2( 0.0 , 1.0 )*d)-GetPixel(uv-vec2( 0.0 , 1.0 )*d).xy );
vec2 dz = vec2(dx.y,dy.y) * 3.0;
d = (vec2(1.0)/uTexSize) * 2.0;
dx = ( 2.0 * GetBlur1(uv+vec2( 1.0 , 0.0 )*d) - 2.0*GetBlur1(uv-vec2( 1.0 , 0.0 )*d).xy )*0.5;
dy = ( 2.0 * GetBlur1(uv+vec2( 0.0 , 1.0 )*d) - 2.0*GetBlur1(uv-vec2( 0.0 , 1.0 )*d).xy )*0.5;
dz +=vec2(dx.y,dy.y);
vec3 bg = pow(length(dz)*0.8+0,0.7) + GetBlur2(uv).y*0.4-0.1;
ret = bg*vec3(0.3,0.5,0.7);
ret-=roam_sin.zyx*roam_cos.ywx;
ret = mix(ret,vec3(0.2,0.1, 0.0),GetPixel(uv + vec2(dx.x,dy.x)*(vec2(1.0)/uTexSize) * 18.0).x * 6.0);
ret = mix(ret, 1.0 ,GetPixel(uv).z);
